import{_ as i,l as s,o as e,c as o,v as r,p as n,x as l,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"权重共享压缩","description":"","frontmatter":{"title":"权重共享压缩","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/weight-sharing-compress.md","filePath":"llm/weight-sharing-compress.md","lastUpdated":1789023840000}'),m={name:"llm/weight-sharing-compress.md"};function E(_,a,c,A,B,f){const t=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=r('<h1 id="权重共享压缩" tabindex="-1">权重共享压缩 <a class="header-anchor" href="#权重共享压缩" aria-label="Permalink to &quot;权重共享压缩&quot;">​</a></h1><div class="epigraph"><p>多层用同一套 FFN，或输入输出嵌入绑成一张表：参数按份数下降，深度变成反复应用，而不是反复存。</p><footer>—— Lan et al., ALBERT, ICLR 2020；Dehghani et al., Universal Transformers, ICLR 2019；嵌入绑定见 Press &amp; Wolf, 2017</footer></div><p><a href="/llm/vocab-pruning">上一课</a> 减词表行数。本课行还在，<strong>同一参数被多处引用</strong>：层间共享、输入输出 tying。缺口是压缩课序的最后一刀——不剪、不量化、不分解，只让一份 \\(W\\) 服务多次前向。后课 <a href="/llm/perplexity-eval-pitfalls">困惑度评测的陷阱</a> 会拿 PPL 当压缩验收，本课先声明共享改了有效深度与词表几何，PPL 更不能当充分统计量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(L\\) 层独立参数，容量随 \\(L\\) 涨，显存也涨。ALBERT 跨层共享：所有层（或分组）用同一套注意力与 FFN，深度仍在，只是反复应用同一函数。Universal Transformers 把这写成显式循环。Press 与 Wolf、Inan 等人把输入嵌入与输出分类头绑成同一矩阵，立刻去掉一张 \\(|V|\\times d\\)。问题是：共享之后，层间特化消失，表示必须靠反复迭代与位置信息区分深度；tying 则强迫隐空间与词空间同一套基。</p><p>这与 <a href="/llm/lora">LoRA</a> 的多任务适配器相反：LoRA 是「一份 \\(W_0\\)，多份小增量」；跨层共享是「一份层参数，多次前向」。服务时 KV 仍按层缓存——共享不自动减 KV，只减权重加载。</p><p><span class="marginnote">把检查点里的层张量指针指到同一存储，是实现；训练时是否共享梯度，是算法。只在推理把层权重平均起来，没有 ALBERT 的训练动态，质量通常更差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练期共享：层参数 ident 绑定，优化器只看到一份。可分组共享（每 \\(g\\) 层一套）在容量与深度特化之间折中。嵌入 tying：\\(\\mathrm{lm\\_head}=E^\\top\\)（或再加偏置），与词表裁剪兼容——先 tying 再裁行。事后共享：把已训的 \\(L\\) 层平均或用 TIES 合并成一套再循环，属于模型合并向深度轴的迁移，需短愈合，不能当无损压缩。</p><p>验收：同等参数的独立层小模型 vs 共享大深度，比的是深度迭代是否换回容量。不要与「7B 共享成一份还叫 7B」混报有效参数。</p>',10)),(e(),n(h,null,{default:l(()=>[d(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22L%20%E5%A5%97%E5%B1%82%E5%8F%82%E6%95%B0%22%5D%20--%3E%20SH%5B%22%E7%BB%91%E5%AE%9A%E4%B8%BA%201%20%E5%A5%97%E6%88%96%20L%2Fg%20%E5%A5%97%22%5D%0A%20%20E%5B%22embedding%22%5D%20--%3E%20TIE%5B%22%E4%B8%8E%20lm_head%20%E7%BB%91%E5%AE%9A%22%5D%0A%20%20SH%20--%3E%20FWD%5B%22%E6%B7%B1%E5%BA%A6%E4%BB%8D%E5%BE%AA%E7%8E%AF%20L%20%E6%AC%A1%22%5D%0A%20%20FWD%20--%3E%20KV%5B%22KV%20%E4%BB%8D%E6%8C%89%E5%B1%82%E5%AD%98%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>未共享时每层可学不同函数。共享后，一层网络被当成迭代算子 \\(x\\leftarrow f(x)\\)，位置编码或层下标嵌入若还在，才能让第 \\(\\ell\\) 次应用与第 \\(\\ell{+}1\\) 次不同。没有层下标，纯共享接近循环，过深会振荡或饱和。tying 让「谁在词表里相近」与「谁在隐空间相近」锁死，对分类头校准有益，对需要把头空间扭开的任务有害。</p><p>压缩账：权重字节降，激活与 KV 不降。Decode 带宽墙若由权重主导，共享有收益；若由 KV 主导，收益接近零。这与 MoE「参数大、激活小」对偶：共享是「参数小、激活次数仍多」。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把层共享写成免费的深度缩放。不要在已经高度特化的推理模型上突然绑层还不愈合。量化应对共享的那一份做一次 <a href="/llm/gptq">GPTQ</a>，不要按层重复量化同一张量却用不同校准激活。压缩进阶到此结束：下一课起，数字怎么来本身会骗人。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>跨层共享减权重份数，不减 KV；深度变成迭代同一 \\(f\\)。</li><li>嵌入 tying 立刻去掉一张 \\(|V|\\times d\\)，并锁词空间与隐空间。</li><li>事后平均层 ≠ ALBERT 式训练共享，需要愈合。</li><li>报有效参数，不要报「循环次数 × 单层」当独立容量。</li><li>出处：Lan et al., ALBERT；Dehghani et al., Universal Transformers；Press &amp; Wolf, 2017。</li></ul>',7))])}const u=i(m,[["render",E]]);export{T as __pageData,u as default};
